
.panel {
  background: var(--aw-panel);
  border: 1px solid var(--aw-line);
  border-radius: var(--aw-radius);
  box-shadow: var(--aw-shadow);
  padding: 18px;
}

.panel-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  margin-bottom: 14px;
}

.eyebrow {
  color: var(--aw-accent-2);
  font-size: 13px;
  letter-spacing: 0.18em;
}

.ghost-btn {
  border: 1px solid rgba(124, 199, 255, 0.4);
  background: rgba(124, 199, 255, 0.08);
  color: var(--aw-text);
  border-radius: 999px;
  padding: 8px 14px;
  cursor: pointer;
}

.hero-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.hero-card {
  background: var(--aw-panel-soft);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 18px;
  padding: 14px;
}

.card-title,
.progress-row,
.meta-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.card-title strong {
  color: var(--aw-accent);
}

.hero-main {
  margin: 10px 0 0;
  color: var(--aw-text);
  line-height: 1.6;
}

.meta-row {
  margin-top: 10px;
  color: var(--aw-muted);
  font-size: 12px;
  flex-wrap: wrap;
}

.track {
  flex: 1;
  height: 10px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  overflow: hidden;
}

.fill {
  height: 100%;
  background: linear-gradient(90deg, var(--aw-accent), var(--aw-accent-2));
}

.world-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
}

.meta-chip {
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  padding: 8px 12px;
  color: var(--aw-muted);
  font-size: 13px;
}

.focus-box {
  margin-top: 14px;
  border-radius: 18px;
  padding: 14px;
  background:
    radial-gradient(circle at top right, rgba(136, 255, 214, 0.12), transparent 32%), rgba(255, 255, 255, 0.04);
}

.focus-label {
  color: var(--aw-warn);
  font-size: 13px;
}

.focus-box p {
  margin: 8px 0 0;
  line-height: 1.7;
}

@media (max-width: 720px) {
  .hero-grid {
    grid-template-columns: 1fr;
  }

  .panel-head {
    align-items: flex-start;
    flex-direction: column;
  }
}
