
.overlay {
  position: fixed;
  inset: 0;
  background: rgba(4, 8, 14, 0.78);
  backdrop-filter: blur(6px);
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 14px;
  z-index: 9999;
}

.modal {
  width: min(1040px, 100%);
  max-height: 88vh;
  overflow: auto;
  background: linear-gradient(180deg, rgba(10, 18, 30, 0.98), rgba(18, 29, 48, 0.98));
  border-radius: 28px;
  border: 1px solid var(--aw-line);
  box-shadow: var(--aw-shadow);
  padding: 20px;
}

.modal-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
}

.eyebrow {
  color: var(--aw-accent-2);
  font-size: 12px;
  letter-spacing: 0.18em;
}

.modal-head h3 {
  margin: 8px 0 0;
}

.close-btn {
  border: 1px solid rgba(255, 255, 255, 0.16);
  width: 40px;
  height: 40px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--aw-text);
  cursor: pointer;
}

.record-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 18px;
}

.record-card {
  border-radius: 20px;
  padding: 16px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.record-top {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.record-top p {
  margin: 6px 0 0;
  color: var(--aw-muted);
  font-size: 13px;
}

.record-badges {
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: var(--aw-warn);
  font-size: 12px;
  text-align: right;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 14px;
}

.detail-label {
  color: var(--aw-accent);
  font-size: 12px;
}

.detail-grid p,
.history-item p,
.empty {
  margin: 6px 0 0;
  line-height: 1.6;
}

.tags-block,
.history-block {
  margin-top: 14px;
}

.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}

.tag {
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(124, 199, 255, 0.14);
  font-size: 12px;
}

.tag.soft {
  background: rgba(255, 255, 255, 0.08);
}

.tag.visible {
  background: rgba(136, 255, 214, 0.14);
}

.tag.locked {
  color: var(--aw-muted);
  border: 1px dashed rgba(255, 255, 255, 0.14);
}

.history-list {
  display: grid;
  gap: 10px;
  margin-top: 10px;
}

.history-item {
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
  padding: 12px;
}

.empty {
  color: var(--aw-muted);
}

@media (max-width: 900px) {
  .record-list,
  .detail-grid {
    grid-template-columns: 1fr;
  }
}
