
.panel {
  background: var(--aw-panel);
  border: 1px solid var(--aw-line);
  border-radius: var(--aw-radius);
  box-shadow: var(--aw-shadow);
  padding: 18px;
}

.section-title {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: baseline;
  margin-bottom: 14px;
}

.hint {
  color: var(--aw-muted);
  font-size: 12px;
}

.people-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.person-card {
  padding: 16px;
  border-radius: 18px;
  background:
    radial-gradient(circle at top right, rgba(124, 199, 255, 0.12), transparent 30%), rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.person-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.person-head p {
  margin: 6px 0 0;
  color: var(--aw-muted);
  font-size: 13px;
}

.species {
  color: var(--aw-accent-2);
  white-space: nowrap;
}

.status,
.summary {
  line-height: 1.65;
  font-size: 13px;
}

.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 10px 0;
}

.tag {
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--aw-text);
  font-size: 12px;
}

.summary {
  color: var(--aw-warn);
}

@media (max-width: 720px) {
  .people-grid {
    grid-template-columns: 1fr;
  }

  .section-title {
    flex-direction: column;
  }
}
