
.shell {
  width: 100%;
  max-width: 920px;
  margin: 0 auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 14px;
}

@media (max-width: 780px) {
  .shell {
    padding: 8px;
  }

  .grid {
    grid-template-columns: 1fr;
  }
}
